def make_card(title, author, year):
    return f"{title} by {author} ({year})"


values = ["Dune", "Frank Herbert", 1965]
record = {"year": 1937, "title": "The Hobbit", "author": "J.R.R. Tolkien"}
base_tags = ["fiction", "classic"]
extra_tags = ["sci-fi"]
defaults = {"font": "serif", "size": 11, "dark": False}
user = {"dark": True, "size": 13}

print(make_card(*values))
print(make_card(**record))
print([*base_tags, "favorite", *extra_tags])
print({**defaults, **user})
